import { sql } from 'drizzle-orm'
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core'

// Column names are derived from property names (camelCase → snake_case) via
// `casing: 'snake_case'` in both the Drizzle client and drizzle.config.ts.

/** UUIDv7 primary key generated by PostgreSQL 18 (time-ordered, index friendly). */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`)

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow()

export const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date())

export const timestamptz = () => timestamp({ withTimezone: true })

/** Case-insensitive text (emails). Requires the `citext` extension. */
export const citext = customType<{ data: string }>({ dataType: () => 'citext' })

/** Time range, e.g. '[2026-10-27 10:00+05:30,2026-10-27 12:00+05:30)'. */
export const tstzrange = customType<{ data: string; driverData: string }>({
  dataType: () => 'tstzrange',
})

export const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' })
